        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeAlienProvider.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface AlienProvider: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeAlienProvider.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface AlienProvider: handle missing in uniffiClone")
            }
        },
        request: { (
            uniffiHandle: UInt64,
            target: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteU64,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> AlienResponse in
                guard let uniffiObj = try? FfiConverterTypeAlienProvider.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try await uniffiObj.request(
                     target: try FfiConverterTypeAlienTarget_lift(target)
                )
            }

            let uniffiHandleSuccess = { (returnValue: AlienResponse) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultU64(
                        returnValue: FfiConverterTypeAlienResponse_lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultU64(
                        returnValue: 0,
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsyncWithError(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                lowerError: FfiConverterTypeAlienError_lower,
                droppedCallback: uniffiOutDroppedCallback
            )
        },
        getEndpoint: { (
            uniffiHandle: UInt64,
            chain: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> String in
                guard let uniffiObj = try? FfiConverterTypeAlienProvider.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.getEndpoint(
                     chain: try FfiConverterTypeChain_lift(chain)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterString.lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeAlienError_lower
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceAlienProvider> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceAlienProvider>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

