public struct FfiConverterTypeGemGateway: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = GemGateway

    public static func lift(_ handle: UInt64) throws -> GemGateway {
        return GemGateway(unsafeFromHandle: handle)
    }

    public static func lower(_ value: GemGateway) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> GemGateway {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: GemGateway, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


