    func exportRecoveryPhrase(keystoreId: String, password: Data) throws  -> [String]
    
    func migrateV3(v3Path: String, v3Password: Data, newPassword: Data, walletId: String) throws  -> GemStoredSecretMigration
    
    func previewImport(`import`: GemImportType) throws  -> GemWalletImport
    
    func sign(keystoreId: String, chain: Chain, input: GemSignerInput, password: Data) throws  -> [GemSignedTransaction]
    
    func signAuth(keystoreId: String, chain: Chain, hash: Data, password: Data) throws  -> String
    
}
open class GemKeystore: GemKeystoreProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_gemstone_fn_clone_gemkeystore(self.handle, $0) }
    }
public convenience init(baseDir: String)throws  {
    let handle =
        try rustCallWithError(FfiConverterTypeGemstoneError_lift) {
        uniffiCallStatus in
    uniffi_gemstone_fn_constructor_gemkeystore_new(
        FfiConverterString.lower(baseDir),uniffiCallStatus
    )
}
    self.init(unsafeFromHandle: handle)
}

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_gemstone_fn_free_gemkeystore(handle, $0) }
    }

    

    
