enum AlienError: Swift.Error, Equatable, Hashable {

    
    
    case RequestError(msg: String
    )
    case ResponseError(msg: String
    )
    case Http(status: UInt16, len: UInt32
    )

    

    

    
}

#if compiler(>=6)
extension AlienError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAlienError: FfiConverterRustBuffer {
    typealias SwiftType = AlienError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AlienError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .RequestError(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .ResponseError(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Http(
            status: try FfiConverterUInt16.read(from: &buf), 
            len: try FfiConverterUInt32.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AlienError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .RequestError(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .ResponseError(msg):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Http(status,len):
            writeInt(&buf, Int32(3))
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterUInt32.write(len, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
