enum SwapperError: Swift.Error, Equatable, Hashable {

    
    
    case NotSupportedChain
    case NotSupportedAsset
    case NoAvailableProvider
    case InputAmountError(minAmount: String?
    )
    case InvalidRoute
    case ComputeQuoteError(String
    )
    case TransactionError(String
    )
    case NoQuoteAvailable

    

    

    
}

#if compiler(>=6)
extension SwapperError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSwapperError: FfiConverterRustBuffer {
    typealias SwiftType = SwapperError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SwapperError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotSupportedChain
        case 2: return .NotSupportedAsset
        case 3: return .NoAvailableProvider
        case 4: return .InputAmountError(
            minAmount: try FfiConverterOptionString.read(from: &buf)
            )
        case 5: return .InvalidRoute
        case 6: return .ComputeQuoteError(
            try FfiConverterString.read(from: &buf)
            )
        case 7: return .TransactionError(
            try FfiConverterString.read(from: &buf)
            )
        case 8: return .NoQuoteAvailable

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SwapperError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .NotSupportedChain:
            writeInt(&buf, Int32(1))
        
        
        case .NotSupportedAsset:
            writeInt(&buf, Int32(2))
        
        
        case .NoAvailableProvider:
            writeInt(&buf, Int32(3))
        
        
        case let .InputAmountError(minAmount):
            writeInt(&buf, Int32(4))
            FfiConverterOptionString.write(minAmount, into: &buf)
            
        
        case .InvalidRoute:
            writeInt(&buf, Int32(5))
        
        
        case let .ComputeQuoteError(v1):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .TransactionError(v1):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .NoQuoteAvailable:
            writeInt(&buf, Int32(8))
        
        }
    }
}


